// sow-149: which branded banner stands in for a news item that has no image of its own. One banner per news
// category (AI/ML, Security, ...) under /brand/feature/news/, generated by scripts/generate-news-feature-images.mjs
// from the news worker's category list; the generic category-archive banner is the last resort for a category
// the generator has not seen, so a fallback can never itself 404. Node-free and dependency-free, so the site
// component and the client-ui bundle import the same rule.

export const NEWS_FEATURE_DIR = '/brand/feature/news/';
export const GENERIC_FEATURE_IMAGE = '/brand/feature/feature-category.png';

/** The twelve categories the news worker classifies into, in its own order (kept in step by a unit test). */
export const NEWS_CATEGORY_SLUGS = Object.freeze([
  'ai-ml', 'web-dev', 'frameworks-libraries', 'open-source', 'security', 'devops-cloud',
  'programming-languages', 'hardware', 'blockchain', 'energy', 'business-funding', 'other',
]);

/** `AI/ML` -> `ai-ml`, `Business/Funding` -> `business-funding`: lowercase, every non-alphanumeric run to one dash. */
export function newsCategorySlug(name) {
  return String(name ?? '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}

/**
 * The banner URL for a news item's category. A known category gets its own banner; anything else (an empty
 * value, a category added to the worker before the generator ran, junk) gets the generic banner.
 */
export function newsFeatureImage(category, { base = '' } = {}) {
  const slug = newsCategorySlug(category);
  const path = slug && NEWS_CATEGORY_SLUGS.includes(slug) ? `${NEWS_FEATURE_DIR}${slug}.png` : GENERIC_FEATURE_IMAGE;
  return base ? String(base).replace(/\/$/, '') + path : path;
}
